mod camera;
mod components;

use dioxus::prelude::*;

/// Generated by `dx build`/`dx serve` from `tailwind.css`. Compiling it in
/// rather than going through the dx asset pipeline keeps plain `cargo run`
/// working, at the cost of needing a `dx build` after changing classes.
static STYLES: &str = include_str!("../assets/tailwind.css");

fn main() {
    tracing_subscriber::fmt::init();
    dioxus::launch(App);
}

#[component]
fn App() -> Element {
    rsx! {
        document::Title { "Vdr "}
        style { {STYLES} }
        div { class: "flex h-full flex-col gap-4 p-6",
            components::Camera {}
        }
    }
}
